//	key with a different body, or while the first request is still running,
//	returns a 409. An empty key, or one longer than 256 characters, returns a
//	400 `invalid_idempotency_key`. [Learn
//	more](https://resend.com/docs/dashboard/emails/idempotency-keys)
//	to: The recipients. For multiple addresses, send an array of strings. Each
//	value can include a friendly name, for example `Ada Lovelace
//	<ada@example.org>`. Each address is `email@example.com` or `Name
//	<email@example.com>`. An address that is not valid returns a 422.
//	cc: The CC recipients. For multiple addresses, send an array of strings.
//	Each address is `email@example.com` or `Name <email@example.com>`. An
//	address that is not valid returns a 422.
//	bcc: The BCC recipients. For multiple addresses, send an array of strings.
//	Each address is `email@example.com` or `Name <email@example.com>`. An
//	address that is not valid returns a 422.
//	subject: The subject. Max 2000 characters. A string that is only whitespace,
//	or that contains a line break, is rejected.
//	html: The HTML body.
//	text: The plain text body.
//	attachments: Files to store on the draft. Each one needs `content`,
//	`filename` and `content_type`. A `path` without `content` returns a 422, and
//	when both are sent, `path` is ignored. A `content_id` returns a 422. The
//	files on a draft can total at most 25 MB. An empty file or a blocked file
//	type returns a 422.
//	threadId: The Thread ID to reply in. Must be sent with `reply_to_email_id`.
//	replyToEmailId: The Email ID to reply to, as returned in `data[].id` by the
//	list thread emails endpoint. Must be sent with `thread_id`.
func InboxesCreateDraft(ctx context.Context, clientConfig ClientConfig, params InboxesCreateDraftParams, opts ...RequestOption) (*CreateInboxDraftResponseSuccess, error) {
	inboxId := params.InboxId
	idempotencyKey := params.IdempotencyKey
	to := params.To
	cc := params.Cc
	bcc := params.Bcc
	subject := params.Subject
	html := params.Html
	text := params.Text
	attachments := params.Attachments
	threadId := params.ThreadId
	replyToEmailId := params.ReplyToEmailId

	if err := ValidateUuid("inbox_id", inboxId); err != nil {
		return nil, err
	}

	if idempotencyKey != nil {
		if err := ValidateLength("Idempotency-Key", *idempotencyKey, LengthOpts{Min: Ptr[int](1), Max: Ptr[int](256)}); err != nil {
			return nil, err
		}
	}

	if to != nil && to.Value != nil {
		if err := ValidateItems("to", *to.Value, LengthOpts{Max: Ptr[int](50)}); err != nil {
			return nil, err
		}
	}

	if cc != nil && cc.Value != nil {
		if err := ValidateItems("cc", *cc.Value, LengthOpts{Max: Ptr[int](50)}); err != nil {
			return nil, err
		}
	}

	if bcc != nil && bcc.Value != nil {
		if err := ValidateItems("bcc", *bcc.Value, LengthOpts{Max: Ptr[int](50)}); err != nil {
			return nil, err
		}
	}

	if subject != nil && subject.Value != nil {
		if err := ValidateLength("subject", string(*subject.Value), LengthOpts{Min: Ptr[int](1), Max: Ptr[int](2000)}); err != nil {
			return nil, err
		}
	}

	if threadId != nil {
		if err := ValidateUuid("thread_id", *threadId); err != nil {
			return nil, err
		}
	}

	if replyToEmailId != nil {
		if err := ValidateUuid("reply_to_email_id", *replyToEmailId); err != nil {
			return nil, err
		}
	}

	resp, err := DoCfg[CreateInboxDraftResponseSuccess](ctx, &clientConfig, "POST", fmt.Sprintf("/inboxes/%s/drafts", EncodePathSegment(inboxId)), &RequestOpts{
		Body: map[string]any{
			"to":                to,
			"cc":                cc,
			"bcc":               bcc,
			"subject":           subject,
			"html":              html,
			"text":              text,
			"attachments":       attachments,
			"thread_id":         threadId,
			"reply_to_email_id": replyToEmailId,
		},
		Headers: OperationHeaders(map[string]any{
			"Idempotency-Key": idempotencyKey,
		}),
		OperationID: "InboxesCreateDraft",
		Options:     opts,
	})
	if err != nil {
		return nil, err
	}
	return &resp.Data, nil
}

